public class SalesBars:Control {
 public List<string> Names=new List<string>();public List<decimal> Actual=new List<decimal>(),Target=new List<decimal>();public bool Daily;ToolTip tip=new ToolTip();int lastTip=-1;
 static readonly CultureInfo AR=CultureInfo.GetCultureInfo("es-AR");
 public SalesBars(){DoubleBuffered=true;BackColor=Color.White;Height=220;Dock=DockStyle.Fill;}
 static string Money(decimal n){return n.ToString("C0",AR);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Names.Count==0)return;var g=e.Graphics;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;if(Daily){DrawDaily(g);return;}decimal max=Math.Max(1m,Actual.Concat(Target).DefaultIfEmpty(0m).Max());int row=Math.Max(49,(Height-3)/Names.Count);for(int i=0;i<Names.Count;i++){int y=i*row;Color color=i==2?DashboardTheme.Teal:DashboardTheme.Blue;DashboardTheme.Text(g,Names[i],new Rectangle(0,y,105,23),9.5f,DashboardTheme.Ink,FontStyle.Bold);string ratio=Target[i]>0?(Actual[i]/Target[i]*100).ToString("N1",AR)+" %":"Sin objetivo";DashboardTheme.Text(g,ratio,new Rectangle(Width-100,y,100,23),10,color,FontStyle.Bold);float w=Math.Max(20,Width-118);float actual=(float)(Math.Max(0,Actual[i])/max)*w,target=(float)(Math.Max(0,Target[i])/max)*w;int barY=y+28;using(var grey=new SolidBrush(DashboardTheme.Line))using(var brush=new SolidBrush(color)){g.FillRectangle(grey,0,barY,w,9);g.FillRectangle(brush,0,barY,actual,9);}if(target>0){using(var pen=new Pen(DashboardTheme.Ink,2))g.DrawLine(pen,target,barY-3,target,barY+12);}string amounts=Money(Actual[i])+"  /  "+Money(Target[i]);DashboardTheme.Text(g,amounts,new Rectangle(0,y+40,Width-2,20),8.5f,DashboardTheme.Muted,FontStyle.Regular);}}
 void DrawDaily(Graphics g){float left=51,right=Width-7,top=10,bottom=Height-30,h=Math.Max(10,bottom-top);decimal high=Math.Max(1,Actual.Concat(Target).DefaultIfEmpty(0m).Max()),low=Math.Min(0,Actual.Concat(Target).DefaultIfEmpty(0m).Min()),range=high-low;for(int j=0;j<=4;j++){decimal val=high-range*j/4;float y=top+h*j/4;using(var pen=new Pen(DashboardTheme.Line))g.DrawLine(pen,left,y,right,y);string axis=Math.Abs(val)>=1000000?(val/1000000).ToString("0.#",AR)+" M":Math.Abs(val)>=1000?(val/1000).ToString("0",AR)+" k":val.ToString("0",AR);DashboardTheme.Text(g,axis,new Rectangle(0,(int)y-9,46,18),8,DashboardTheme.Muted,FontStyle.Regular);}float baseline=top+(float)(high/range)*h,slot=Math.Max(1,(right-left)/Math.Max(1,Names.Count));for(int i=0;i<Names.Count;i++){float x=left+i*slot+slot*.1f;float a=(float)(Actual[i]/range)*h,b=(float)(Target[i]/range)*h;using(var blue=new SolidBrush(DashboardTheme.Blue))using(var teal=new SolidBrush(DashboardTheme.Teal)){g.FillRectangle(blue,x,baseline-Math.Max(0,a),Math.Max(1,slot*.33f),Math.Abs(a));g.FillRectangle(teal,x+slot*.36f,baseline-Math.Max(0,b),Math.Max(1,slot*.33f),Math.Abs(b));}int stride=Math.Max(1,(int)Math.Ceiling(Names.Count/9.0));if(i%stride==0)DashboardTheme.Text(g,Names[i],new Rectangle((int)x-4,(int)bottom+7,48,18),8,DashboardTheme.Muted,FontStyle.Regular);}using(var pen=new Pen(Color.FromArgb(181,193,208)))g.DrawLine(pen,left,baseline,right,baseline);}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(Names.Count==0)return;int index=Daily?(int)Math.Floor((e.X-51)/Math.Max(1f,(Width-58f)/Names.Count)):e.Y/Math.Max(49,(Height-3)/Names.Count);if(index>=0&&index<Names.Count&&index!=lastTip){lastTip=index;tip.SetToolTip(this,Names[index]+(Daily?" · Taller ":" · Actual ")+Actual[index].ToString("C2",AR)+(Daily?" · Mostrador ":" · Objetivo ")+Target[index].ToString("C2",AR));}}
 protected override void Dispose(bool disposing){if(disposing)tip.Dispose();base.Dispose(disposing);}
}
