 void ResetDates(){changing=true;from.MinDate=to.MinDate=cutoff.MinDate=DateTimePicker.MinimumDateTime;from.MaxDate=to.MaxDate=cutoff.MaxDate=DateTimePicker.MaximumDateTime;var a=SalesMath.Start(P);var b=SalesMath.End(P);var s=store.Get(P);from.Value=a;to.Value=s==null?b:s.Cutoff;cutoff.Value=s==null?(DateTime.Today<a?a:DateTime.Today>b?b:DateTime.Today):s.Cutoff;foreach(var d in new[]{from,to,cutoff}){d.MinDate=a;d.MaxDate=b;}changing=false;RefreshData();}
