 bars.Names=new List<string>{"Total","Taller","Mostrador"};var full=all.Where(x=>snap!=null&&x.Date<=snap.Cutoff).ToList();bars.Actual=new List<decimal>{full.Sum(x=>x.Sale),full.Where(x=>x.Sector=="Taller").Sum(x=>x.Sale),full.Where(x=>x.Sector=="Mostrador").Sum(x=>x.Sale)};bars.Target=new List<decimal>{g.Total,g.Total*g.Taller/100,g.Total*(100-g.Taller)/100};bars.Invalidate();
