 daily.Names.Clear();daily.Actual.Clear();daily.Target.Clear();for(var d=from.Value.Date;d<=to.Value.Date;d=d.AddDays(1)){daily.Names.Add(d.ToString("dd/MM"));daily.Actual.Add(selected.Where(x=>x.Date==d&&x.Sector=="Taller").Sum(x=>x.Sale));daily.Target.Add(selected.Where(x=>x.Date==d&&x.Sector=="Mostrador").Sum(x=>x.Sale));}daily.Invalidate();
