 if(calendar){int done=SalesMath.Workdays(SalesMath.Start(P),snap.Cutoff,store.Holidays),remaining=SalesMath.Workdays(snap.Cutoff.AddDays(1),SalesMath.End(P),store.Holidays);projection.Text+="Proyección: "+(done>0?M(sale/done*(done+remaining)):"—")+"\nNecesario por día: "+(remaining>0?M(Math.Max(0,diff)/remaining):(diff>0?"Período cerrado":"Objetivo alcanzado"))+"\n"+done+" días laborables transcurridos · "+remaining+" restantes";
 var previous=store.Get(prev);if(previous==null)comparison.Text="Sin datos del período anterior.";else if(!store.HasCalendar(SalesMath.Start(prev),SalesMath.End(prev)))comparison.Text="Comparación pendiente del calendario nacional del período anterior.";else{int available=SalesMath.Workdays(SalesMath.Start(prev),previous.Cutoff,store.Holidays);int compare=Math.Min(done,available);var currentEnd=SalesMath.EquivalentCutoff(P,compare,store.Holidays);var previousEnd=SalesMath.EquivalentCutoff(prev,compare,store.Holidays);decimal currentPartial=compare==0?0:Filter(all.Where(x=>x.Date<=currentEnd)).Sum(x=>x.Sale),previousPartial=compare==0?0:Filter(store.Visible(previous).Where(x=>x.Date<=previousEnd)).Sum(x=>x.Sale);comparison.Text="Comparación: "+compare+" días laborables · Actual "+M(currentPartial)+" / Anterior "+M(previousPartial)+(previousPartial!=0?" · Variación "+((currentPartial-previousPartial)/Math.Abs(previousPartial)*100).ToString("N2",AR)+" %":" · Sin base porcentual")+"\nPeríodo anterior "+(previous.Cutoff==SalesMath.End(prev)?"cerrado":"INCOMPLETO hasta "+previous.Cutoff.ToString("dd/MM"))+": "+M(Filter(store.Visible(previous)).Sum(x=>x.Sale))+" · Actual acumulado: "+M(sale);}}
 else{projection.Text+="Proyección pendiente: cargá el calendario nacional de los años necesarios.";comparison.Text="Comparación por días laborables pendiente del calendario nacional.";}
