 void Parameters(object sender,EventArgs e){var goal=store.GetGoal(P);using(var f=new Form{Text="Objetivos y parámetros · "+P.ToString("MMMM yyyy",AR),Size=new Size(520,460),StartPosition=FormStartPosition.CenterParent}){var layout=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(15),WrapContents=false};f.Controls.Add(layout);NumericUpDown total=Numeric(goal.Total,1000000000000),taller=Numeric(goal.Taller,100),margin=Numeric(goal.Margin,100);var split=new Label{AutoSize=true};Action update=()=>split.Text="Mostrador: "+(100-taller.Value).ToString("N2",AR)+" % · "+M(total.Value*(100-taller.Value)/100);total.ValueChanged+=delegate{update();};taller.ValueChanged+=delegate{update();};layout.Controls.Add(new Label{Text="Objetivo total en pesos",AutoSize=true});layout.Controls.Add(total);layout.Controls.Add(new Label{Text="Distribución Taller (%)",AutoSize=true});layout.Controls.Add(taller);layout.Controls.Add(split);update();layout.Controls.Add(new Label{Text="Margen objetivo único (%)",AutoSize=true});layout.Controls.Add(margin);var intern=new CheckBox{Text="Incluir Interno",Checked=store.Intern,AutoSize=true};var warranty=new CheckBox{Text="Incluir Garantía",Checked=store.Warranty,AutoSize=true};var courtesy=new CheckBox{Text="Incluir Cortesía",Checked=store.Courtesy,AutoSize=true};layout.Controls.Add(intern);layout.Controls.Add(warranty);layout.Controls.Add(courtesy);layout.Controls.Add(new Label{Text="Los interruptores se aplican a todos los períodos de esta app.\nLos importes conservan su signo. Se excluyen también sus tickets.",AutoSize=true});var save=Button("Guardar",delegate{var old=new Goal{Total=goal.Total,Taller=goal.Taller,Margin=goal.Margin};bool oi=store.Intern,ow=store.Warranty,oc=store.Courtesy;try{goal.Total=total.Value;goal.Taller=taller.Value;goal.Margin=margin.Value;store.Intern=intern.Checked;store.Warranty=warranty.Checked;store.Courtesy=courtesy.Checked;store.Save();f.DialogResult=DialogResult.OK;}catch(Exception ex){goal.Total=old.Total;goal.Taller=old.Taller;goal.Margin=old.Margin;store.Intern=oi;store.Warranty=ow;store.Courtesy=oc;MessageBox.Show(ex.Message);}});layout.Controls.Add(save);f.ShowDialog(this);}RefreshData();}

 void EnsureCalendars(){if(loadingCalendar)return;var years=new List<int>();for(int y=SalesMath.Start(P.AddMonths(-1)).Year;y<=P.Year;y++)if(!store.CalendarYears.Contains(y))years.Add(y);if(years.Count==0)return;loadingCalendar=true;calendarNotice="Consultando calendario nacional...";var worker=new System.ComponentModel.BackgroundWorker();worker.DoWork+=delegate(object sender,System.ComponentModel.DoWorkEventArgs e){var result=new Dictionary<int,List<DateTime>>();ServicePointManager.SecurityProtocol=(SecurityProtocolType)3072;foreach(int year in years){using(var web=new CalendarClient()){web.Encoding=System.Text.Encoding.UTF8;string json=web.DownloadString("https://api.argentinadatos.com/v1/feriados/"+year);var items=new JavaScriptSerializer().Deserialize<List<Dictionary<string,object>>>(json);var days=items.Where(x=>x.ContainsKey("tipo")&&(x["tipo"].ToString()=="inamovible"||x["tipo"].ToString()=="trasladable")).Select(x=>DateTime.ParseExact(x["fecha"].ToString(),"yyyy-MM-dd",CultureInfo.InvariantCulture)).Where(d=>d.Year==year).Distinct().ToList();if(days.Count<10)throw new Exception("Calendario incompleto para "+year);result[year]=days;}}e.Result=result;};worker.RunWorkerCompleted+=delegate(object sender,System.ComponentModel.RunWorkerCompletedEventArgs e){loadingCalendar=false;if(IsDisposed){worker.Dispose();return;}if(e.Error!=null)calendarNotice="No se pudo consultar el calendario; revisá Calendario nacional.";else{var oldDays=new HashSet<DateTime>(store.Holidays);var oldYears=new HashSet<int>(store.CalendarYears);try{foreach(var pair in (Dictionary<int,List<DateTime>>)e.Result){store.Holidays.UnionWith(pair.Value);store.CalendarYears.Add(pair.Key);}store.Save();calendarNotice="Calendario nacional actualizado.";}catch(Exception ex){store.Holidays=oldDays;store.CalendarYears=oldYears;calendarNotice="No se pudo guardar calendario: "+ex.Message;}}RefreshData();worker.Dispose();};worker.RunWorkerAsync();}
 class CalendarClient:WebClient {protected override WebRequest GetWebRequest(Uri address){var r=base.GetWebRequest(address);r.Timeout=15000;return r;}}
 void Calendar(object sender,EventArgs e){using(var f=new Form{Text="Feriados nacionales · calendario por año",Size=new Size(630,530),StartPosition=FormStartPosition.CenterParent}){var y=new NumericUpDown{Minimum=2000,Maximum=2100,Value=P.Year,Location=new Point(20,20)};var text=new TextBox{Multiline=true,ScrollBars=ScrollBars.Vertical,Location=new Point(20,115),Size=new Size(570,280),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Bottom};Action load=()=>text.Text=String.Join(Environment.NewLine,store.Holidays.Where(d=>d.Year==(int)y.Value).OrderBy(d=>d).Select(d=>d.ToString("yyyy-MM-dd")).ToArray());y.ValueChanged+=delegate{load();};load();f.Controls.Add(y);f.Controls.Add(new Label{Text="Una fecha por línea (aaaa-mm-dd). Solo feriados nacionales.\nNo incluir días no laborables opcionales ni feriados provinciales.",Location=new Point(20,65),AutoSize=true});f.Controls.Add(text);var download=new Button{Text="Consultar calendario en línea",Location=new Point(180,18),Width=240};download.Click+=delegate{try{ServicePointManager.SecurityProtocol=(SecurityProtocolType)3072;string json;using(var web=new WebClient()){web.Encoding=System.Text.Encoding.UTF8;json=web.DownloadString("https://api.argentinadatos.com/v1/feriados/"+(int)y.Value);}var items=new JavaScriptSerializer().Deserialize<List<Dictionary<string,object>>>(json);var days=items.Where(x=>x.ContainsKey("tipo")&&(x["tipo"].ToString()=="inamovible"||x["tipo"].ToString()=="trasladable")).Select(x=>DateTime.ParseExact(x["fecha"].ToString(),"yyyy-MM-dd",CultureInfo.InvariantCulture)).Where(d=>d.Year==(int)y.Value).OrderBy(d=>d).ToList();if(days.Count<10)throw new Exception("El calendario recibido está incompleto.");text.Text=String.Join(Environment.NewLine,days.Select(d=>d.ToString("yyyy-MM-dd")).ToArray());MessageBox.Show("Calendario consultado en ArgentinaDatos. Revisá las fechas contra el calendario nacional antes de guardar.");}catch(Exception ex){MessageBox.Show("No se pudo consultar el calendario. Podés ingresar las fechas manualmente.\n"+ex.Message);}};f.Controls.Add(download);var official=new LinkLabel{Text="Abrir calendario oficial de Argentina",AutoSize=true,Location=new Point(20,410),Anchor=AnchorStyles.Left|AnchorStyles.Bottom};official.LinkClicked+=delegate{System.Diagnostics.Process.Start("https://www.argentina.gob.ar/feriados");};f.Controls.Add(official);var save=new Button{Text="Guardar calendario",Location=new Point(380,440),Width=210,Anchor=AnchorStyles.Bottom|AnchorStyles.Right};save.Click+=delegate{var oldDays=new HashSet<DateTime>(store.Holidays);var oldYears=new HashSet<int>(store.CalendarYears);try{var parsed=new HashSet<DateTime>();foreach(string line in text.Lines.Where(x=>!String.IsNullOrWhiteSpace(x))){var d=DateTime.ParseExact(line.Trim(),"yyyy-MM-dd",CultureInfo.InvariantCulture);if(d.Year!=(int)y.Value)throw new Exception("Todas las fechas deben corresponder al año seleccionado.");parsed.Add(d);}if(parsed.Count<10)throw new Exception("Revisá el calendario completo del año antes de guardarlo.");store.Holidays.RemoveWhere(d=>d.Year==(int)y.Value);store.Holidays.UnionWith(parsed);store.CalendarYears.Add((int)y.Value);store.Save();f.DialogResult=DialogResult.OK;}catch(Exception ex){store.Holidays=oldDays;store.CalendarYears=oldYears;MessageBox.Show(ex.Message);}};f.Controls.Add(save);f.ShowDialog(this);}RefreshData();}
